const fs = require('fs');

const a = new Array(9).fill(0);

function main() {
    for (let k = 1; k <= 8; k++) {
        const l = (1 << k) - 1;
        const r = 1 << (k - 1);
        const v = l * r;
        a[k] = v;
    }

    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    const n = parseInt(input[0], 10);

    for (let k = 8; k >= 1; k--) {
        if (n >= a[k] && n % a[k] === 0) {
            console.log(a[k]);
            return;
        }
    }
}

