		r := 1 << (k - 1)
		v := l * r
		a[k] = int64(v)
	}

	n := helper.ReadInt64()
	for k := int64(8); k >= 1; k-- {
		if n >= a[k] && n % a[k] == 0 {
			fmt.Println(a[k])
			return
		}
	}
}

type SHelper struct {
	file *os.File
	scanner *bufio.Scanner
}

func (this *SHelper) Init() {
	this.file = os.Stdin
	this.scanner = bufio.NewScanner(this.file)
	this.scanner.Split(bufio.ScanWords)
}

